import { useState, type ButtonHTMLAttributes, type CSSProperties } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

const STAR =
  "M9.362,9.158c0,0-3.16,0.35-5.268,0.584c-0.19,0.023-0.358,0.15-0.421,0.343s0,0.394,0.14,0.521c1.566,1.429,3.919,3.569,3.919,3.569c-0.002,0-0.646,3.113-1.074,5.19c-0.036,0.188,0.032,0.387,0.196,0.506c0.163,0.119,0.373,0.121,0.538,0.028c1.844-1.048,4.606-2.624,4.606-2.624s2.763,1.576,4.604,2.625c0.168,0.092,0.378,0.09,0.541-0.029c0.164-0.119,0.232-0.318,0.195-0.505c-0.428-2.078-1.071-5.191-1.071-5.191s2.353-2.14,3.919-3.566c0.14-0.131,0.202-0.332,0.14-0.524s-0.23-0.319-0.42-0.341c-2.108-0.236-5.269-0.586-5.269-0.586s-1.31-2.898-2.183-4.83c-0.082-0.173-0.254-0.294-0.456-0.294s-0.375,0.122-0.453,0.294C10.671,6.26,9.362,9.158,9.362,9.158z"

export interface StarFavoriteToggleProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "color"> {
  pressed?: boolean
  defaultPressed?: boolean
  onPressedChange?: (pressed: boolean) => void
  /** 收藏后的填充色。不传时使用主色。 */
  color?: string
}

export function StarFavoriteToggle({
  pressed,
  defaultPressed = false,
  onPressedChange,
  color = "var(--primary)",
  className,
  style,
  type = "button",
  ...props
}: StarFavoriteToggleProps) {
  const reduced = usePrefersReducedMotion()
  const [uncontrolled, setUncontrolled] = useState(defaultPressed)
  const on = pressed ?? uncontrolled
  const painted = { "--star-color": color, ...style } as CSSProperties

  return (
    <button
      {...props}
      aria-label={props["aria-label"] ?? "收藏"}
      aria-pressed={on}
      className={cn("cursor-pointer border-0 bg-transparent p-1", className)}
      data-pressed={on ? "true" : "false"}
      data-reduced={reduced ? "true" : "false"}
      data-slot="star-favorite-toggle"
      onClick={(event) => {
        props.onClick?.(event)
        if (event.defaultPrevented) return
        const next = !on
        if (pressed === undefined) setUncontrolled(next)
        onPressedChange?.(next)
      }}
      style={painted}
      type={type}
    >
      <svg
        aria-hidden="true"
        className={cn("size-12", reduced ? "transition-none" : "transition hover:scale-110")}
        style={{ fill: on ? "var(--star-color)" : "var(--muted-foreground)" }}
        viewBox="0 0 24 24"
      >
        <path d={STAR} />
      </svg>
    </button>
  )
}
